 const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
 function exactNumber(value){return typeof value==="number"&&Number.isFinite(value)?String(value):"Недоступно"}
 function formatCount(value){return Number.isInteger(value)?String(value):exactNumber(value)}
 function formatRate(value){return exactNumber(value)}
