 function formatPosterior(value){return exactNumber(value)}
 const fmt=x=>x===undefined||x===null?"Недоступно":typeof x==="number"?exactNumber(x):Array.isArray(x)?x.map(fmt).join(", "):x&&typeof x==="object"?Object.entries(x).map(([k,v])=>k+": "+fmt(v)).join(" · "):typeof x==="string"&&["NaN","Infinity","-Infinity","undefined"].includes(x)?"Недоступно":String(x);
 function val(label,value,help,formatter=fmt){return `<div class="ux-value"><span>${esc(label)}</span><b>${esc(formatter(value))}</b>${help?tip(help):""}</div>`}
 function tip(key){return `<button class="help-button" data-help="${esc(key)}" aria-label="Довідка: ${esc(key)}">?</button>`}
 function list(xs){return (xs||[]).map(x=>`<li>${esc(x)}</li>`).join("")}
 function chart(title,subtitle,svg,legend){return `<figure class="ux-chart"><h3>${title}</h3><p>${subtitle}</p>${svg}<figcaption>${legend}</figcaption></figure>`}
 function bars(values,labels,title,ylabel,selected){let max=Math.max(...values,1e-12),w=680,h=220,g=35,b=h-g;return chart(title,`x: edge ID · y: ${ylabel}; шкала від нуля`,`<svg role="img" aria-label="${title}" viewBox="0 0 ${w} ${h}"><line x1="${g}" y1="${b}" x2="${w-5}" y2="${b}" class="ux-axis"/>${values.map((v,i)=>{let x=g+i*39,hh=(b-20)*v/max;return `<g><title>${esc(labels[i])}: ${exactNumber(v)}</title><rect x="${x}" y="${b-hh}" width="25" height="${hh}" class="${i===selected?"ux-selected":"ux-bar"}"/><text x="${x+12}" y="${b+15}" text-anchor="middle">${i}</text></g>`}).join("")}<text x="4" y="15">${exactNumber(max)}</text></svg>`,`Обраний символ f=${app.symbol}; дані — фактичний trace.`)}
 function linePlot(series,selected,title,ylabel,caption){let vals=series.flatMap(s=>s.values),lo=Math.min(0,...vals),hi=Math.max(0,...vals),w=720,h=220,px=i=>35+i*660/Math.max(1,series[0].values.length-1),py=v=>15+(hi-v)*185/((hi-lo)||1);return chart(title,`x: символ f · y: ${ylabel}`,`<svg role="img" aria-label="${title}" viewBox="0 0 ${w} ${h}"><line class="ux-axis" x1="35" y1="${py(0)}" x2="700" y2="${py(0)}"/><line class="ux-marker" x1="${px(selected)}" y1="10" x2="${px(selected)}" y2="205"/>${series.map((s,k)=>`<polyline class="ux-line ux-c${k}" points="${s.values.map((v,i)=>px(i)+","+py(v)).join(" ")}"><title>${esc(s.name)}</title></polyline>`).join("")}<text x="4" y="14">${exactNumber(hi)}</text><text x="4" y="205">${exactNumber(lo)}</text></svg>`,caption+` · f=${selected}.`)}
 function formulaMarkup(r,parameters){const vec=x=>`(${x.map(v=>fmt(v)).join(", ")})`;return `<details class="ux-formula" open><summary>Формула та підстановка</summary><p><b>Загальна формула</b></p><math display="block"><mrow><msub><mi>s</mi><mrow><mi>f</mi><mo>+</mo><mn>1</mn></mrow></msub><mo>=</mo><msub><mi>α′</mi></msub><msub><mi>s</mi><mi>f</mi></msub><mo>+</mo><msub><mi>K̃</mi></msub><mo>⊙</mo><msub><mi>ε</mi><mi>f</mi></msub></mrow></math><p><b>Підстановка з фактичного trace</b>: α′=${esc(parameters.alpha_prime)}; s[f]=${esc(vec(r.pre_state.fluctuating_iq))}; K̃=${esc(vec(parameters.k_tilde))}; ε[f]=${esc(vec(r.innovation))}.</p><p>Внесок згасання з trace: α′s[f]=${esc(vec(r.alpha_contribution))}; внесок корекції з trace: K̃⊙ε[f]=${esc(vec(r.correction_contribution))}.</p><p><b>Результат trace</b>: s[f+1]=${esc(vec(r.post_state.fluctuating_iq))}.</p><p>full[f]=s[f]+μ₀: ${esc(vec(r.pre_state.fluctuating_iq))}+${esc(vec(parameters.mu0))}=${esc(vec(r.pre_state.full_iq))}; після оновлення full[f+1]=${esc(vec(r.post_state.full_iq))}.</p><p>Джерело: [A] с. 4, формула (1) — структура рекурсії підтримана частково; проєктний tick, innovation semantics і μ₀ anchor не є повністю підтвердженими джерелом.</p></details>`}
