 function viewUX(name){const panel=$("view-"+name);if(!panel)throw new Error(`Unknown Demo Studio view: ${name}`);let breadcrumb=panel.querySelector("#ux-breadcrumb"),explainer=panel.querySelector("#ux-explainer");if(!breadcrumb){breadcrumb=document.createElement("div");breadcrumb.id="ux-breadcrumb";panel.prepend(breadcrumb)}if(!explainer){explainer=document.createElement("div");explainer.id="ux-explainer";panel.insertBefore(explainer,breadcrumb.nextSibling)}app.lastView=app.currentView||"demo";app.currentView=name;document.querySelectorAll(".view").forEach(x=>x.classList.toggle("active",x===panel));document.querySelectorAll(".nav-item").forEach(x=>x.classList.toggle("active",x.dataset.view===name));breadcrumb.textContent="Симуляція  ›  "+(info[name]?.[0]||name);explainer.innerHTML=`<b>Що тут відбувається?</b> ${esc(info[name]?.[1]||"Огляд.")} <b>Навіщо це потрібно?</b> Перейдіть між кроками, зберігаючи f=${app.symbol}. <b>Що означає результат?</b> ${esc(info[name]?.[2]||"Значення походять із фактичних даних.")}`;document.body.dataset.uxView=name;window.scrollTo(0,0)}
 function renderSummary(){const t=app.trace;if(!t)return `<div class="ux-placeholder"><h2>Крок 1 — Налаштувати. Крок 2 — Запустити.</h2><p>До запуску runtime даних немає. Оберіть F=32 детермінований пресет, потім натисніть кнопку.</p>${tip("runtime.F")}</div>`;const scientific=document.body.dataset.mode==="scientific",noiseNames={zero:"Без шуму",low_amplitude_a:"Детермінований шум малої амплітуди",alternating_b:"Детермінований змінний шум"},channelGain=t.input?.channel_gain;return `<section class="ux-summary"><h2>Що отримано? <small>${scientific?"DEMO RESULTS · NOT A PERFORMANCE STUDY":"РЕЗУЛЬТАТИ ДЕМОНСТРАЦІЇ · НЕ ДОСЛІДЖЕННЯ ЯКОСТІ"}</small></h2>${cards([["Символи",t.input.symbol_count,null,formatCount],["Інформаційні біти",t.input.information_bits.length,null,formatCount],["Комплексні відліки",t.input.sample_count,null,formatCount],[scientific?"Channel gain a":"Коефіцієнт підсилення каналу a",channelGain,null,formatCoefficient],[scientific?"Noise fixture":"Модель шуму",scientific?t.input.noise_fixture:(noiseNames[t.input.noise_fixture]||"Недоступно")]])}<div class="ux-policies">${t.arms.map(a=>`<article><h3>${esc(a.candidate_id)}</h3>${cards([["Помилкові біти",a.reference_comparison.bit_errors,null,formatCount],["BER",a.reference_comparison.ber,null,formatRate],["SER",a.reference_comparison.ser,null,formatRate],["Статус",scientific?"Completed · fixture":"Завершено · демонстрація"]])}</article>`).join("")}</div><p>${scientific?"One deterministic run does not establish a statistical advantage.":"Один детермінований запуск не встановлює статистичної переваги."}</p></section>`}
 function appendPhaseHelp(){const html=val("\u041a\u0440\u043e\u043a \u0444\u0430\u0437\u0438 \u0394\u03c6","\u03c0/4","source.phase_increment");for(const target of document.querySelectorAll("#demo-summary .ux-placeholder, #demo-summary .ux-summary, #symbol-detail .ux-values")){if(!target.querySelector("[data-help=\"source.phase_increment\"]"))target.insertAdjacentHTML("beforeend",html)}}
