 function renderStageDetailUX(){const s=app.metadata.stages.find(x=>x.stage_id===app.stage),r=row(),v=s&&stageValue(s.stage_id,r,arm());if(!s){$("stage-detail").innerHTML="<p>Оберіть один з 28 кроків нижче.</p>";return}$("stage-detail").innerHTML=`<h2>${esc(s.name)} ${tip("runtime.transition_edge")}</h2><p>${esc(stageExplanations[Number(s.stage_id)-1])}</p><p><b>Формула:</b> ${esc(s.formula)} · <b>одиниця:</b> ${esc(s.unit)}</p><p><b>Походження:</b> ${esc(s.raw_derived_provenance)} · ${esc(s.provenance)}</p>${r?cards([["Вхід",fmt(v.inputs)],["Вихід",fmt(v.outputs)],["Символ f",r.symbol_index],["Відліки",r.sample_indices.join(", ")]]):`<p class="ux-placeholder">Запустіть demo, щоб побачити фактичний trace.</p>`}${v?.unavailable?`<p class="ux-note">${esc(v.unavailable)}</p>`:""}<details><summary>Технічні подробиці</summary><pre>${esc(JSON.stringify(v,null,2))}</pre></details>`}
 function renderPipelineUX(){ $("pipeline-grid").innerHTML=app.metadata.stages.map(s=>`<button class="stage-block ux-stage ${app.stage===s.stage_id?"selected":""}" data-stage="${s.stage_id}"><b>${s.stage_id}</b> ${esc(s.name)}<small>${app.trace?"Дані trace готові":"Після запуску"}</small></button>`).join("");document.querySelectorAll("[data-stage]").forEach(b=>b.onclick=()=>{app.stage=b.dataset.stage;renderPipelineUX();renderStageDetailUX()});renderStageDetailUX()}
 function renderSymbolUX(){let r=row(),t=app.trace?.transmitter;if(!r){$("symbol-detail").innerHTML='<p class="ux-placeholder">Дані символу з’являться після запуску симуляції.</p>';return}orig.renderSymbol.call(window);let bits=app.trace.input.information_bits.slice(app.symbol*2,app.symbol*2+2);$("symbol-detail").innerHTML=`<h2>Символ f=${app.symbol}</h2>${cards([["Вхідні біти",bits.join("")],["Стан encoder",fmt(r.encoder_state_before)],["Переход edge",r.selected_encoder_edge_id],["Фаза b",r.phase_index],["Спостережений I/Q",fmt(r.observed_iq)]])}${chart("Сигнал, шум і приймання","x: відлік n · y: амплітуда I/Q (нормовані одиниці)",`<svg viewBox="0 0 720 220"><line class="ux-axis" x1="35" y1="110" x2="710" y2="110"/>${["transmitted_samples","noise_samples","received_samples"].map((k,j)=>{let x=t[k].slice(app.symbol*8,app.symbol*8+8),vv=x.flatMap(z=>[z.real,z.imag]),m=Math.max(.05,...vv.map(Math.abs)),pts=vv.map((v,i)=>35+i*95+","+ (110-v/m*85)).join(" ");return `<polyline class="ux-line ux-c${j}" points="${pts}"><title>${k} I,Q</title></polyline>`}).join("")}<text x="35" y="210">${r.sample_indices[0]}</text><text x="650" y="210">${r.sample_indices.at(-1)}</text></svg>`,"Передані відліки, deterministic disturbance та прийняті відліки; фактичні 8 samples.")}<details><summary>Значення I/Q по відліках</summary>${r.sample_indices.map((n,i)=>val("n="+n,"Tx "+fmt(r.transmitted_samples[i])+" · шум "+fmt(r.noise_samples[i])+" · Rx "+fmt(r.received_samples[i]))).join("")}</details>`}
 function installTrellisPresentation(){if($("trellis-display-mode"))return;const toolbar=$("trellis-mode").closest(".toolbar");toolbar.insertAdjacentHTML("afterend",`<div class="trellis-presentation-controls"><label>Подання <select id="trellis-display-mode"><option value="overview">Оглядова решітка</option><option value="detail">Детальний перехід</option></select></label><label>Масштаб <input id="trellis-projector-zoom" type="range" min="100" max="160" step="10" value="100"><output id="trellis-projector-zoom-out">100%</output></label><button id="trellis-show-all" class="secondary" type="button">Показати всі переходи</button></div><div class="trellis-legend"><span class="legend-viterbi">Шлях conditional Viterbi</span><span class="legend-reference">Шлях encoder для reference бітів</span><span class="legend-selected">Вибраний символ f=${app.symbol}</span></div><article id="trellis-edge-detail" class="card trellis-edge-detail" aria-live="polite"></article>`);$("edge-table").hidden=true;$("trellis-display-mode").onchange=e=>{m11hATrellisMode=e.target.value;renderTrellisUX()};$("trellis-projector-zoom").oninput=e=>{m11hATrellisZoom=Number(e.target.value)/100;$("trellis-projector-zoom-out").value=`${e.target.value}%`;renderTrellisUX()};$("trellis-show-all").onclick=()=>{m11hAShowAll=!m11hAShowAll;renderTrellisUX()}}
 function renderATrellisDetail(){const edges=app.metadata.edges,id=Number(app.edge)||0,e=edges[id],a=arm(),r=row(),live=r?.edge_definitions?.[id],scientific=document.body.dataset.mode==="scientific";if(!e){$("trellis-edge-detail").textContent="Перехід недоступний.";return}const title=scientific?`Edge ${id}`:`Перехід ee${id}`;$("trellis-edge-detail").innerHTML=`<h3>${title} · символ f=${app.symbol}</h3><dl><dt>Джерело → ціль</dt><dd>${esc(fmt(e.source_state))} → ${esc(fmt(e.target_state))}</dd><dt>Вхідні біти → вихідні біти</dt><dd>${e.input_bits.join("")} → ${e.output_bits.join("")}</dd><dt>Фаза</dt><dd>${live?formatCount(live.phase_index):"Недоступно без trace"}</dd><dt>Метрика</dt><dd>${live?formatMetric(r.candidate_metrics[id]):"Недоступно без trace"}</dd><dt>Posterior</dt><dd>${live?formatPosterior(r.posterior[id]):"Недоступно без trace"}</dd><dt>Шлях</dt><dd>${a?.viterbi.decoded_edge_path.includes(id)?"Viterbi":r?.selected_encoder_edge_id===id?"Reference та вибраний символ":"Не входить до підсвіченого шляху"}</dd></dl><p>Огляд не підписує всі ребра. У детальному режимі підписано лише вибраний перехід.</p>`}
 function renderTrellisGraph(){const api=window.HFTCMTrellisProjector;if(!api)return;const states=app.metadata.states,source=arm(),allEdges=app.metadata.edges,selected=source?.symbols[app.symbol]?.selected_encoder_edge_id??null,live=row()?.edge_definitions||[];const stateIds=states.map((_,i)=>i),stateLabels=Object.fromEntries(states.map((s,i)=>[i,s.join(" · ")]));const edges=allEdges.map((e,i)=>({id:e.edge_id,sourceId:states.findIndex(s=>JSON.stringify(s)===JSON.stringify(e.source_state)),targetId:states.findIndex(s=>JSON.stringify(s)===JSON.stringify(e.target_state)),inputId:e.input_bits[0]+2*e.input_bits[1],input:e.input_bits.join(""),output:e.output_bits.join(""),sourceLabel:e.source_state.join(""),targetLabel:e.target_state.join(""),phase:live[i]?.phase_index}));const svg=api.renderSvg({stateIds,stateLabels,edges,mode:m11hATrellisMode,selectedEdgeId:Number(app.edge)||0,selectedSymbolEdgeId:selected,viterbiEdges:source?.viterbi.decoded_edge_path||[],referenceEdges:source?.symbols.map(x=>x.selected_encoder_edge_id)||[],zoom:m11hATrellisZoom,idPrefix:"encoder-a"});$("trellis-canvas").innerHTML=svg;const graph=$("trellis-canvas").querySelector("svg");graph.querySelectorAll("[data-projector-edge]").forEach(path=>{const select=()=>{app.edge=Number(path.dataset.projectorEdge);m11hASelectedEdge=app.edge;$("hypothesis-select").value=String(app.edge);renderTrellisUX();renderCompareUX()};path.addEventListener("click",select);path.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();select()}})});}
 function renderTrellisUX(){orig.renderTrellis();$("edge-table").classList.remove("ux-scientific-only");$("edge-table").setAttribute("aria-label","Усі 16 переходів кодера A");$("edge-table").hidden=!m11hAShowAll;$("trellis-show-all").textContent=m11hAShowAll?"Сховати таблицю переходів":"Показати всі переходи";if($("trellis-display-mode").value!==m11hATrellisMode)$("trellis-display-mode").value=m11hATrellisMode;const svg=document.querySelector(".trellis-svg"),state=window.HFTCMSignalExplorerState;if($("trellis-mode").value==="graph")renderTrellisGraph();else if(svg){svg.querySelectorAll(".edge-label").forEach(label=>{label.hidden=m11hATrellisMode!=="detail"||Number(label.textContent)!==Number(app.edge)});if(state){svg.querySelector(".trellis-window-highlight")?.remove();const start=Number($("trellis-offset").value)||0,lo=Math.max(start,state.startSymbol),hi=Math.min(start+24,state.endSymbol);if(hi>lo){const ns="http://www.w3.org/2000/svg",rect=document.createElementNS(ns,"rect");rect.setAttribute("class","trellis-window-highlight");rect.setAttribute("x",String(50+(lo-start)*90));rect.setAttribute("y","18");rect.setAttribute("width",String(Math.max(6,(hi-lo)*90)));rect.setAttribute("height","315");rect.setAttribute("fill","#ef9f2830");rect.setAttribute("stroke","#b36a00");rect.setAttribute("stroke-width","3");svg.insertBefore(rect,svg.firstChild)}}}renderATrellisDetail();$("trellis-edge-detail").classList.toggle("ux-hidden",m11hATrellisMode!=="detail")}
 function renderBPreviewGraph(){const data=m11hBPreview,host=$("encoder-b-graph");if(!data||!host)return;const states=Array.from({length:16},(_,id)=>id),labels=Object.fromEntries(data.trellis.filter((e,i)=>i%4===0).map(e=>[e.state_id,e.state.join(" · ")]));const edges=data.trellis.map(e=>({id:e.branch_id,sourceId:e.state_id,targetId:e.target_state_id,inputId:e.input_bits[0]+2*e.input_bits[1],input:e.input_bits.join(""),output:e.output_bits.join(""),sourceLabel:e.state.join(""),targetLabel:e.target_state.join("")}));const selectedSymbol=Math.min(m11hBSelectedSymbol,Math.max(0,data.symbol_count-1)),selectedSymbolEdgeId=data.branch_ids[selectedSymbol];host.innerHTML=window.HFTCMTrellisProjector.renderSvg({stateIds:states,stateLabels:labels,edges,mode:m11hBMode,selectedEdgeId:m11hBSelectedEdge,selectedSymbolEdgeId,viterbiEdges:[],referenceEdges:data.branch_ids,zoom:m11hBZoom,idPrefix:"encoder-b"});host.querySelectorAll("[data-projector-edge]").forEach(path=>{const select=()=>{m11hBSelectedEdge=Number(path.dataset.projectorEdge);m11hBMode="detail";$("encoder-b-display-mode").value="detail";renderBPreviewGraph()};path.addEventListener("click",select);path.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();select()}})});const e=data.trellis.find(edge=>edge.branch_id===m11hBSelectedEdge)||data.trellis[0];$("encoder-b-edge-detail").innerHTML=`<h4>Перехід Q=${e.branch_id} · вибраний символ f=${selectedSymbol}</h4><dl><dt>Стан джерела → стан цілі</dt><dd>${e.state_id} (${e.state.join("")}) → ${e.target_state_id} (${e.target_state.join("")})</dd><dt>Вхід X0X1 → вихід C2C1C0</dt><dd>${e.input_bits.join("")} → ${e.output_bits.join("")}</dd><dt>Фаза</dt><dd>недоступна: source mapping не встановлений</dd><dt>Метрика</dt><dd>недоступна: receiver не реалізований</dd><dt>posterior</dt><dd>недоступний: немає узгодженої моделі приймача</dd><dt>Параметр B</dt><dd>${e.manipulation_parameter_B}</dd></dl>`;const table=$("encoder-b-transition-table");table.hidden=!m11hBShowAll;$("encoder-b-show-all").textContent=m11hBShowAll?"Сховати таблицю переходів":"Показати всі переходи";$("encoder-b-selected-symbol").value=String(selectedSymbol);$("encoder-b-selected-symbol-out").value=String(selectedSymbol);}
 function installBPreviewControls(data){m11hBPreview=data;m11hBMode="overview";m11hBSelectedEdge=Number(data.branch_ids[0])||0;m11hBSelectedSymbol=0;m11hBZoom=1;m11hBShowAll=false;const result=$("encoder-b-result"),table=result.querySelector(".table-wrap");table.id="encoder-b-transition-table";table.classList.add("trellis-transition-table");table.hidden=true;table.insertAdjacentHTML("beforebegin",`<section class="b-trellis-projector"><div class="trellis-presentation-controls"><label>Подання <select id="encoder-b-display-mode"><option value="overview">Оглядова решітка</option><option value="detail">Детальний перехід</option></select></label><label>Масштаб <input id="encoder-b-zoom" type="range" min="100" max="160" step="10" value="100"><output id="encoder-b-zoom-out">100%</output></label><label>Вибраний символ f <input id="encoder-b-selected-symbol" type="range" min="0" max="${Math.max(0,data.symbol_count-1)}" value="0"><output id="encoder-b-selected-symbol-out">0</output></label><button id="encoder-b-show-all" class="secondary" type="button">Показати всі переходи</button></div><div class="trellis-legend"><span class="legend-reference">Шлях фактичної вхідної послідовності</span><span class="legend-selected">Вибраний символ</span><span>Viterbi не запускається для B</span></div><div id="encoder-b-graph" class="trellis-wrap b-trellis-wrap"></div><article id="encoder-b-edge-detail" class="card trellis-edge-detail" aria-live="polite"></article></section>`);$("encoder-b-display-mode").onchange=e=>{m11hBMode=e.target.value;renderBPreviewGraph()};$("encoder-b-zoom").oninput=e=>{m11hBZoom=Number(e.target.value)/100;$("encoder-b-zoom-out").value=`${e.target.value}%`;renderBPreviewGraph()};$("encoder-b-selected-symbol").oninput=e=>{m11hBSelectedSymbol=Number(e.target.value);renderBPreviewGraph()};$("encoder-b-show-all").onclick=()=>{m11hBShowAll=!m11hBShowAll;renderBPreviewGraph()};renderBPreviewGraph()}
 function renderEstimatorUX(){let a=arm(),r=row();if(!r){$("estimator-view").innerHTML='<p class="ux-placeholder">Стан оцінювача з’явиться після запуску.</p>';return}const scientific=document.body.dataset.mode==="scientific",labels=scientific?["OLD STATE · s[f]","DECAY · α′s[f]","INNOVATION · ε[f]","CORRECTION · K̃⊙ε","NEW STATE · s[f+1]","Full state · s+μ₀"]:["Стан до оновлення · s[f]","Згасання · α′s[f]","Інновація · ε[f]","Корекція · K̃⊙ε","Стан після оновлення · s[f+1]","Повний стан · s+μ₀"],s=r.pre_state.fluctuating_iq;$("estimator-view").innerHTML=`<h2>${scientific?"Causal update order":"Причинний порядок"} · символ f=${app.symbol}</h2>${cards([[labels[0],s],[labels[1],r.alpha_contribution],[labels[2],r.innovation],[labels[3],r.correction_contribution],[labels[4],r.post_state.fluctuating_iq],[labels[5],r.post_state.full_iq]])}${formulaMarkup(r,a.parameters)}<p>${scientific?"The next symbol uses post-state; current predictions were computed from pre-state.":"Наступний символ використовує стан після оновлення; поточні прогнози обчислено зі стану до оновлення."} ${app.symbol===a.symbols.length-1?(scientific?"No next symbol; prediction is unavailable.":"Наступного символу немає; прогноз недоступний."):`${scientific?"Next pre-state:":"Наступний стан до оновлення:"} `+fmt(a.symbols[app.symbol+1].pre_state.full_iq)}</p>${linePlot([{name:"I",values:a.symbols.map(x=>x.post_state.full_iq[0])},{name:"Q",values:a.symbols.map(x=>x.post_state.full_iq[1])}],app.symbol,scientific?"Estimated I/Q trajectory":"Оцінена I/Q траєкторія",scientific?"normalized amplitude":"нормована амплітуда",scientific?"Full post-state; marker is selected symbol.":"Повний стан після оновлення; маркер — обраний символ.")}`}
 function renderCompareUX(){orig.renderCompare();if(app.trace&&app.trace.arms.length>1){document.querySelector("#compare-view").insertAdjacentHTML("afterbegin",`<p>Спільний received SHA-256: ${esc(app.trace.input.received_sha256)} · f=${app.symbol}</p>`)}}
 function renderDecodeUX(){const a=arm(),box=$("ux-decode"),scientific=document.body.dataset.mode==="scientific";if(!a||!app.trace){box.innerHTML=`<p class="ux-placeholder">${scientific?"Conditional Viterbi path will appear after an explicit F=32 demo run.":"Шлях умовного декодера Вітербі з’явиться після явного запуску F=32 демонстрації."}</p>`;return}const rows=a.viterbi.decoded_edge_path.map((edge,f)=>{const r=a.symbols[f],bits=a.viterbi.decoded_input_pairs[f];return `<tr class="${f===app.symbol?"active":""}"><td>${formatCount(f)}</td><td>${formatCount(r.estimator_tick)}</td><td>${formatCount(edge)}</td><td>${esc(fmt(a.viterbi.state_path[f]))}</td><td>${esc(fmt(a.viterbi.state_path[f+1]))}</td><td>${esc(bits.join(""))}</td><td>${esc(r.input_bit_pair.join(""))}</td><td>${esc(fmt(r.reference_comparison.bit_error_flags))}</td></tr>`}).join("");box.innerHTML=`<h2>${scientific?"Conditional Viterbi · actual path":"Умовний Вітербі · фактичний шлях"}</h2><p>${scientific?"The decoder received frozen metric rows and returned this path. This is the project conditional procedure, not a claim about a complete paper decoder.":"Декодер отримав зафіксовані рядки метрик і повернув цей шлях. Це умовна процедура проєкту, не повний декодер зі статті."}</p>${cards([[scientific?"Decoded bits":"Декодовані біти",a.viterbi.decoded_bits.length,null,formatCount],[scientific?"Bit errors":"Помилки бітів",a.reference_comparison.bit_errors,null,formatCount],["BER",a.reference_comparison.ber,null,formatRate],[scientific?"Symbol errors":"Помилки символів",a.reference_comparison.symbol_errors,null,formatCount],["SER",a.reference_comparison.ser,null,formatRate]])}<div class="ux-table-scroll"><table class="data-table"><thead><tr>${(scientific?["Symbol f","Tick","Decoded edge","State before","State after","Decoded bits","Reference bits","Errors"]:["Символ f","Крок","Перехід декодера","Стан до","Стан після","Декодовані біти","Біти прикладу","Помилки"]).map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows}</tbody></table></div><p>${scientific?`Selected symbol f=${app.symbol}. Reference sequence is from the explicit demo fixture.`:`Підсвічено обраний символ f=${app.symbol}. Еталонна послідовність належить лише демонстраційному прикладу.`}</p>`}
 function renderTablesUX(){let a=app.trace?.arms[Number($("table-arm").value)||0],r=a?.symbols[Number($("table-index").value)||0];if(!r){$("exact-tables").innerHTML='<p class="ux-placeholder">Таблиці з’являться після запуску.</p>';return}const scientific=document.body.dataset.mode==="scientific",edgeLabels=scientific?["Edge","Input","Output","Target","Phase","Metric","Weight"]:["Перехід","Вхід","Вихід","Наступний стан","Фаза","Метрика","Апостеріорна вага"];$("exact-tables").innerHTML=`<h2>${scientific?"16 hypotheses":"16 гіпотез"} · символ f=${formatCount(r.symbol_index)}</h2>${bars(r.candidate_metrics,r.edge_definitions.map((_,i)=>"Edge "+i),scientific?"Candidate metrics":"Метрики кандидатів",scientific?"implementation metric":"метрика реалізації",r.selected_encoder_edge_id)}${bars(r.posterior,r.edge_definitions.map((_,i)=>"Edge "+i),scientific?"Project posterior weights":"Ваги апостеріорного розподілу проєкту",scientific?"normalized weight":"нормована вага",r.selected_encoder_edge_id)}<div class="ux-table-scroll"><table class="data-table"><thead><tr>${edgeLabels.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${r.edge_definitions.map((e,i)=>`<tr class="${app.edge===i?"active":""}"><td>${formatCount(i)}${tip("runtime.candidate_metrics")}</td><td>${e.input_bits.join("")}</td><td>${e.output_bits.join("")}</td><td>${e.target_state.join("")}</td><td>${formatCount(e.phase_index)}</td><td>${formatMetric(r.candidate_metrics[i])}</td><td>${formatPosterior(r.posterior[i])}</td></tr>`).join("")}</tbody></table></div>${scientific?`<details><summary>Exact sample values / CSV export</summary>${r.sample_indices.map((n,i)=>val("sample "+formatCount(n),"Tx "+fmt(r.transmitted_samples[i])+" · Rx "+fmt(r.received_samples[i]))).join("")}</details>`:""}`}
 function renderDefenseUX(){let [title,text]=defense[app.defense],r=row();$("defense-content").innerHTML=`<small>КРОК ${app.defense+1} З 18</small><h2>${esc(title)}</h2><p>${esc(text)}</p>${r?cards([["Обраний символ",app.symbol],["Edge",r.selected_encoder_edge_id],["Фаза",r.phase_index]]):'<p>Запустіть demo, щоб показати фактичні значення.</p>'}<p>Модель реконструйована; джерельні неоднозначності залишаються відкритими.</p>`}
 function category(p){let n=(p.parameter||"").toLowerCase(),g=(p.group||"").toLowerCase();if(n.startsWith("runtime.")||n.startsWith("historical."))return "runtime";if(/metadata|provenance|diagnostic|raw trace|source note/.test(n+" "+g))return "technical";return "core"}
 function formulaData(trace,armIndex,symbolIndex,edgeIndex){let a=trace?.arms?.[armIndex],r=a?.symbols?.[symbolIndex];if(!r)return null;return {f:symbolIndex,edge:edgeIndex,pre:r.pre_state.fluctuating_iq,full:r.pre_state.full_iq,alpha:a.parameters.alpha_prime,k:a.parameters.k_tilde,mu0:a.parameters.mu0,innovation:r.innovation,decay:r.alpha_contribution,correction:r.correction_contribution,post:r.post_state.fluctuating_iq,postFull:r.post_state.full_iq,metric:r.candidate_metrics[edgeIndex],posterior:r.posterior[edgeIndex],ber:{errors:a.reference_comparison.bit_errors,total:a.reference_comparison.total_bits,value:a.reference_comparison.ber},ser:{errors:a.reference_comparison.symbol_errors,total:a.reference_comparison.total_symbols,value:a.reference_comparison.ser},nextAvailable:symbolIndex<a.symbols.length-1}}
 let helpOpener=null;
 function canRestoreFocusTo(element){return element instanceof HTMLElement&&element.isConnected&&!element.matches(":disabled,[tabindex='-1']")}
 function restoreHelpFocus(){const target=canRestoreFocusTo(helpOpener)?helpOpener:$("parameter-search");helpOpener=null;target?.focus()}
