    const selected=window.HFTCMSignalWindow.symbolIndexAtSample(win.startSample,trace.input.symbol_count,SAMPLE_COUNT_PER_SYMBOL);
    window.HFTCMSignalExplorerState={startSample:win.startSample,endSample:win.endSample,startSymbol:Math.floor(win.startSample/SAMPLE_COUNT_PER_SYMBOL),endSymbol:Math.ceil(win.endSample/SAMPLE_COUNT_PER_SYMBOL)};
