      const step=Math.max(1,Math.ceil(spec.xValues.length/20)),labels=spec.xValues.filter((_,i)=>i%step===0).map((x)=>`<text x="${L+(spec.xValues.indexOf(x)+.5)*groupW}" y="${H-B+28}" text-anchor="middle">${x}</text>`).join("");
      return `<svg class="signal-svg" role="img" aria-label="${esc(spec.title)}" viewBox="0 0 ${W} ${H}">${grid}${bars}<line x1="${L}" y1="${zeroY}" x2="${W-R}" y2="${zeroY}" class="signal-axis"/><line x1="${L}" y1="${T}" x2="${L}" y2="${H-B}" class="signal-axis"/>${labels}${legends}<text x="${W/2}" y="${H-4}" text-anchor="middle">${esc(spec.xLabel)}</text><text transform="translate(22 ${H/2}) rotate(-90)" text-anchor="middle">${esc(spec.yLabel)}</text></svg>`;
