    const grid=Array.from({length:3},(_,i)=>{const value=min+(max-min)*i/2,yy=y(value);return `<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" class="signal-grid"/><text x="${L-10}" y="${yy+5}" text-anchor="end">${signalTick(value)}</text>`}).join("");
