      phase:["8PSK фазовий індекс", "s_f=exp(j·2πb_f/8)",`b=${phase}; Δφ=π/4 — phase increment; absolute edge mapping reconstructed`,"trace.transmitter.phase_indices; ADR-002; article v7 p.5"],
