      tx:["Передані 8 відліків", "x[n]=x_f, n=8f…8f+7",`${f*8}…${f*8+7}: ${tx.transmitted_samples.slice(f*8,(f+1)*8).map(v=>`(${exactNumber(v.real)},${exactNumber(v.imag)})`).join("; ")}`,"trace.transmitter.transmitted_samples; rectangular ZOH project rule"],
      gain:["Підсилення каналу", "x_gain[n]=a·x[n]",`a=${exactNumber(t.input.channel_gain)}; gain-applied samples are actual trace values`,"trace.input.channel_gain; M11a deterministic fixture config"],
      noise:["Детермінований шум", "y[n]=a·x[n]+w[n]",`${t.input.noise_fixture}: ${t.input.noise_formula}`,"trace.input.noise_fixture/noise_formula; no RNG / no AWGN SNR claim"],
      received:["Прийняті відліки", "y[n]=a·x[n]+w[n]",tx.received_samples.slice(f*8,(f+1)*8).map(v=>`(${exactNumber(v.real)},${exactNumber(v.imag)})`).join("; "),"trace.transmitter.received_samples; deterministic evaluation buffer"],
