      estimator:["Рекурсивний оцінювач", "s[f+1]=α′·s[f]+K̃⊙ε[f]",`pre=${row.pre_state.fluctuating_iq.map(exactNumber).join(", ")}; innovation=${row.innovation.map(exactNumber).join(", ")}; post=${row.post_state.fluctuating_iq.map(exactNumber).join(", ")}`,"trace.arms[].symbols[].pre_state/post_state; project recursion"],
      viterbi:["Conditional Viterbi", "min-plus over frozen full-frame metric rows",`F=${t.input.symbol_count}; edge at f=${arm.viterbi.decoded_edge_path[f]}; state ${JSON.stringify(arm.viterbi.state_path[f])} → ${JSON.stringify(arm.viterbi.state_path[f+1])}; one full-frame call`,"trace.arms[].viterbi; decoding/reconstruction_viterbi.py"],
