 function m11jInstallStages(){const panel=$("view-pipeline");if(!panel||$("m11j-stage-list"))return;const oldGrid=$("pipeline-grid");if(oldGrid)oldGrid.classList.add("ux-hidden");const detail=$("stage-detail");if(detail)detail.classList.add("ux-hidden");panel.insertAdjacentHTML("beforeend",`<div class="m11j-stage-layout"><nav id="m11j-stage-list" aria-label="Етапи сигналу"></nav><section class="m11j-stage-main"><div id="m11j-stage-status"></div><article class="card m11j-stage-chart"><div class="m11j-chart-heading"><h2 id="m11j-stage-title"></h2><button class="help-button" type="button" data-help="signal.window" aria-label="Довідка про етап">?</button></div><p id="m11j-stage-explanation"></p><div id="m11j-stage-graph"></div></article><dl id="m11j-stage-values" class="m11j-stage-values"></dl><details><summary>Advanced details</summary><div id="m11j-stage-advanced"></div></details><p class="scientific-banner">Показано комплексну огинаючу. Реальний RF hardware, passband upconversion і фізичний багатопроменевий канал тут не моделюються.</p></section></div>`);$("m11j-stage-list").innerHTML=window.HFTCMMinimalistState.SIGNAL_STAGES.map((s,i)=>`<button type="button" data-stage-key="${s.id}" class="m11j-stage-choice"><span>${i+1}. ${esc(s.label)}</span><small>${s.status}</small></button>`).join("");$("m11j-stage-list").querySelectorAll("[data-stage-key]").forEach(b=>b.onclick=()=>{m11jState.currentStage=b.dataset.stageKey;renderM11jStage()});}
 function m11jStageOperands(trace,arm,r,stage){if(!r)return "Недоступно до запуску";const f=app.symbol,tx=trace.transmitter;const map={information:trace.input.information_bits.join(""),encoder:tx.encoded_output_bits[f]?.join("")??"Недоступно",tcm:`${fmt(r.encoder_state_before)} → edge ${r.selected_encoder_edge_id} → ${fmt(r.encoder_state_after)}`,modulation:`b=${r.phase_index}; ${fmt(tx.transmitted_symbols[f])}`,zoh:tx.transmitted_samples.slice(f*8,f*8+8),"tx-output":tx.transmitted_symbols[f],gain:tx.channel_contribution_samples.slice(f*8,f*8+8),noise:tx.noise_samples.slice(f*8,f*8+8),received:tx.received_samples.slice(f*8,f*8+8),observed:r.observed_iq};return map[stage.id]??"Недоступно";}
 function renderM11jStage(){const host=$("m11j-stage-graph");if(!host)return;const stage=window.HFTCMMinimalistState.SIGNAL_STAGES.find(x=>x.id===m11jState.currentStage)||window.HFTCMMinimalistState.SIGNAL_STAGES[0],trace=app.trace,a=arm(),f=app.symbol;$("m11j-stage-list")?.querySelectorAll("[data-stage-key]").forEach(b=>b.classList.toggle("selected",b.dataset.stageKey===stage.id));$("m11j-stage-title").textContent=stage.label;$("m11j-stage-status").innerHTML=`<span class="m11j-status m11j-status-${stage.status.toLowerCase().replaceAll(" ","-")}">${stage.status}</span>`;$("m11j-stage-explanation").textContent=stage.id==="gain"?"У цьому демонстраційному кадрі застосовано лише наявне дійсне підсилення; це не повна HF-модель каналу.":stage.id==="tx-output"||stage.id==="received"?"Позначення передавача/приймача описує модельний complex-envelope порт, а не RF hardware chain.":"Графік побудовано з фактичних значень активного runtime trace.";if(!trace||!a){host.innerHTML='<p class="ux-placeholder">Запустіть симуляцію, щоб побачити фактичні значення.</p>';$("m11j-stage-values").innerHTML="";return}const win=window.HFTCMSignalWindow.calculateSampleWindow(trace.input.sample_count,signalWindowStartSample,Math.min(signalViewWindowSamples,trace.input.sample_count)),spec=signalSpec(stage.chart,trace,a,f,win);host.innerHTML=signalSvg(spec,win,f);const r=a.symbols[f];$("m11j-stage-values").innerHTML=`<dt>Формула</dt><dd><code>${esc(stage.formula)}</code></dd><dt>Поточне значення</dt><dd>${esc(fmt(m11jStageOperands(trace,a,r,stage)))}</dd><dt>Джерело</dt><dd><code>${esc(stage.source)}</code></dd><dt>Вибраний символ</dt><dd>f=${f}; absolute samples ${f*8}…${f*8+7}</dd>`;$("m11j-stage-advanced").textContent=`run=${m11jState.activeRunId??"none"}; stale=${m11jState.stale}; stage=${stage.id}; chart=${stage.chart}; policy=${a.candidate_id}`;}
 function m11jInstallSamples(){const panel=$("view-signal");if(!panel||$("signal-exact-details"))return;const detail=$("signal-stage-detail")?.closest("article");if(detail){const advanced=document.createElement("details");advanced.id="signal-exact-details";advanced.innerHTML="<summary>Точні значення й походження</summary>";advanced.append(detail);panel.append(advanced)}panel.insertAdjacentHTML("beforeend",`<details id="m11j-exact-samples"><summary>Таблиця точних відліків</summary><div id="m11j-sample-table"></div></details>`);const heading=panel.querySelector(".signal-chart-heading");heading?.insertAdjacentHTML("beforeend",`<button type="button" class="help-button" data-help="signal.window" aria-label="Довідка">?</button>`);}
 function renderM11jSampleTable(){const target=$("m11j-sample-table"),t=app.trace?.transmitter;if(!target||!t)return;const start=signalWindowStartSample,end=Math.min(t.received_samples.length,start+signalViewWindowSamples),rows=[];for(let n=start;n<end;n++){const f=Math.floor(n/8),selected=f===app.symbol;rows.push(`<tr class="${selected?"active":""}"><td>${n}</td><td>${fmt(t.transmitted_samples[n])}</td><td>${fmt(t.channel_contribution_samples[n])}</td><td>${fmt(t.noise_samples[n])}</td><td>${fmt(t.received_samples[n])}</td></tr>`)}target.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>Absolute sample n</th><th>Tx I/Q</th><th>Gain-applied I/Q</th><th>Noise I/Q</th><th>Received I/Q</th></tr></thead><tbody>${rows.join("")}</tbody></table></div>`;}
 function m11jInstallHidden(){const panel=$("view-trellis");if(!panel||$("m11j-hidden-tabs"))return;const pane=document.createElement("div");pane.id="m11j-tcm-pane";const preserved=new Set([$("ux-breadcrumb"),$("ux-explainer"),panel.querySelector(":scope > .section-head")]);for(const child of [...panel.children])if(!preserved.has(child))pane.append(child);panel.insertAdjacentHTML("beforeend",`<div id="m11j-hidden-tabs" role="tablist"><button role="tab" aria-selected="true" data-hidden-tab="tcm">Стани TCM-кодера</button><button role="tab" aria-selected="false" data-hidden-tab="channel">Приховані параметри каналу</button></div><section id="m11j-channel-states" class="card" hidden><h2>Приховані параметри каналу</h2><p>У deterministic demo channel Markov/Rician state trajectories, transition probabilities і channel posterior не обчислювалися. Показані project posterior weights стосуються encoder-edge hypotheses і не є оцінкою прихованого стану каналу.</p><span class="m11j-status m11j-status-unavailable">UNAVAILABLE</span></section>`);panel.append(pane);panel.insertAdjacentHTML("beforeend",`<div id="m11j-b-trellis-slot"></div>`);$("m11j-hidden-tabs").querySelectorAll("[data-hidden-tab]").forEach(b=>b.onclick=()=>{m11jState.hiddenTab=b.dataset.hiddenTab;renderM11jHidden()});}
 function renderM11jHidden(){const channel=m11jState.hiddenTab==="channel",pane=$("m11j-channel-states"),tcm=$("m11j-tcm-pane"),encoder=$("interactive-encoder")?.value||"A";if(pane)pane.hidden=!channel;if(tcm)tcm.hidden=channel;$("m11j-hidden-tabs")?.querySelectorAll("[data-hidden-tab]").forEach(b=>b.setAttribute("aria-selected",String(b.dataset.hiddenTab===m11jState.hiddenTab)));if(encoder==="B"){const sec=document.querySelector("#encoder-b-result .b-trellis-projector"),table=$("encoder-b-transition-table"),slot=$("m11j-b-trellis-slot");if(sec&&slot&&!slot.contains(sec))slot.append(sec);if(table&&slot&&!slot.contains(table))slot.append(table);tcm?.classList.add("ux-hidden");if(slot)slot.hidden=channel;return}tcm?.classList.remove("ux-hidden");const slot=$("m11j-b-trellis-slot");if(slot)slot.hidden=true;}
 function m11jInstallDecoding(){const panel=$("view-decode");if(!panel||$("m11j-decode-tabs"))return;panel.insertAdjacentHTML("beforeend",`<nav id="m11j-decode-tabs" role="tablist"><button role="tab" aria-selected="true" data-decode-tab="metrics">Метрики</button><button role="tab" aria-selected="false" data-decode-tab="estimation">Оцінювання</button><button role="tab" aria-selected="false" data-decode-tab="viterbi">Viterbi</button></nav><section id="m11j-decode-view" class="card"></section><details id="m11j-decode-advanced"><summary>Advanced details</summary><div id="m11j-decode-raw"></div></details>`);$("ux-decode")?.classList.add("ux-hidden");$("m11j-decode-tabs").querySelectorAll("[data-decode-tab]").forEach(b=>b.onclick=()=>{m11jState.decodeTab=b.dataset.decodeTab;renderM11jDecoding()});}
 function renderM11jDecoding(){const box=$("m11j-decode-view");if(!box)return;const trace=app.trace,a=arm(),r=row(),f=app.symbol,encoder=$("interactive-encoder")?.value||"A";$("m11j-decode-tabs")?.querySelectorAll("[data-decode-tab]").forEach(b=>b.setAttribute("aria-selected",String(b.dataset.decodeTab===m11jState.decodeTab)));if(encoder==="B"){box.innerHTML='<span class="m11j-status m11j-status-unavailable">UNAVAILABLE</span><h2>Приймач для Encoder B недоступний</h2><p>Фазове маркування B і сумісний receiver/Viterbi не встановлені. Preview B не створює decoded values.</p>';return}if(!trace||!a||!r){box.innerHTML='<p class="ux-placeholder">Запустіть явну симуляцію Encoder A, щоб побачити фактичні metrics, update і Viterbi path.</p>';return}const win=window.HFTCMSignalWindow.calculateSampleWindow(trace.input.sample_count,signalWindowStartSample,Math.min(signalViewWindowSamples,trace.input.sample_count));if(m11jState.decodeTab==="metrics"){const spec=signalSpec("metrics",trace,a,f,win);box.innerHTML=`<h2>16 кандидатних метрик і прогнозів · f=${f}</h2>${signalSvg(spec,win,f)}<p>Фактичні predicted I/Q та squared-residual metrics активного trace; SCI-METRIC-02 залишається OPEN.</p><p>Вибрана метрика: ${formatMetric(r.candidate_metrics[r.selected_encoder_edge_id])} · posterior weight: ${formatPosterior(r.posterior[r.selected_encoder_edge_id])}</p>`;$("m11j-decode-raw").textContent=fmt({predicted_iq:r.predicted_iq,candidate_metrics:r.candidate_metrics,posterior:r.posterior});return}if(m11jState.decodeTab==="estimation"){box.innerHTML=`<h2>Рекурсивне оновлення оцінювача · f=${f}</h2>${linePlot([{name:"Pre I",values:a.symbols.map(x=>x.pre_state.full_iq[0])},{name:"Post I",values:a.symbols.map(x=>x.post_state.full_iq[0])},{name:"Pre Q",values:a.symbols.map(x=>x.pre_state.full_iq[1])},{name:"Post Q",values:a.symbols.map(x=>x.post_state.full_iq[1])}],f,"Повна траєкторія pre/post I/Q","Нормована амплітуда","Обчислено з actual trace; pre-state формує поточні прогнози.")}<p><code>s[f+1]=alpha_prime*s[f]+K_tilde⊙innovation</code></p><p>Pre=${fmt(r.pre_state.full_iq)} · innovation=${fmt(r.innovation)} · post=${fmt(r.post_state.full_iq)}</p>`;$("m11j-decode-raw").textContent=fmt({pre:r.pre_state,innovation:r.innovation,post:r.post_state,posterior:r.posterior});return}const spec=signalSpec("viterbi",trace,a,f,win);box.innerHTML=`<h2>Conditional Viterbi · повний кадр</h2>${signalSvg(spec,win,f)}<p>Decoded bits: <code>${a.viterbi.decoded_bits.join("")}</code></p><p>Фактичний edge: ${a.viterbi.decoded_edge_path[f]} · state ${fmt(a.viterbi.state_path[f])} → ${fmt(a.viterbi.state_path[f+1])}</p><p>20-symbol viewing window не є Viterbi traceback depth η=20.</p>`;$("m11j-decode-raw").textContent=fmt({decoded_edge_path:a.viterbi.decoded_edge_path,state_path:a.viterbi.state_path,decoder_calls:a.viterbi.decoder_calls});}
 function m11jInstallResults(){const panel=$("view-datasets");if(!panel||$("m11j-archive-focus"))return;const summary=$("demo-summary");panel.insertAdjacentHTML("afterbegin",`<section class="card m11j-current-results"><h2>Поточна демонстрація</h2><div id="m11j-current-run-values"></div></section><section id="m11j-archive-focus" class="card"><h2>Архівні наукові експерименти</h2><p>M5–M10 — збережені результати з власним TRAIN/EVALUATION статусом. Один deterministic frame не є статистичним доказом.</p><label>Графік архівного експерименту <select id="m11j-archive-select"><option>Завантаження архіву…</option></select></label><div id="m11j-archive-chart"></div><details id="m11j-archive-advanced"><summary>Advanced: усі архівні таблиці та fidelity inspector</summary></details></section>`);if(summary)$("m11j-current-run-values").append(summary);const advanced=document.createElement("details");advanced.id="m11j-archive-existing";advanced.innerHTML="<summary>Availability та наукові обмеження</summary>";for(const id of ["research-dashboard","coverage-table"]){const el=$(id);if(el)advanced.append(el)}const fidelity=panel.querySelector(".fidelity-card");if(fidelity)advanced.append(fidelity);$("m11j-archive-advanced").append(advanced);$("m11j-archive-select").onchange=()=>renderM11jArchive();fetch("/api/archive-views").then(r=>r.json()).then(d=>{m11jArchiveCharts=d.charts||[];$("m11j-archive-select").innerHTML=m11jArchiveCharts.map((c,i)=>`<option value="${i}">${esc(c.title)} · ${esc(c.status)}</option>`).join("");renderM11jArchive()}).catch(()=>{$("m11j-archive-chart").textContent="Архівні графіки недоступні; дивіться збережені таблиці у Advanced details."});}
 function renderM11jArchive(){const chart=$("m11j-archive-chart"),c=m11jArchiveCharts[Number($("m11j-archive-select")?.value)||0];if(!chart)return;if(!c){chart.innerHTML='<p class="ux-placeholder">Архівних графіків у поточній збірці немає.</p>';return}const graph=c.kind==="ci"?bars(c.series[0].values,["Нижня межа","Оцінка","Верхня межа"],c.title,c.y_label,1):c.kind==="bar"?c.series.map(s=>bars(s.values,c.labels,s.name,c.y_label,0)).join(""):c.series.map(s=>linePlot([{name:s.name,values:s.values}],Math.min(app.symbol,s.values.length-1),c.title,c.y_label,c.caption)).join("");chart.innerHTML=`<span class="m11j-status">${esc(c.status)}</span><p>${esc(c.caption)}</p>${graph}${c.kind==="ci"?`<p>Оцінка ${exactNumber(c.series[0].values[1])}; 95% CI [${exactNumber(c.series[0].values[0])}, ${exactNumber(c.series[0].values[2])}]. Інтервал містить нуль; перевагу не встановлено.</p>`:""}<details><summary>Походження</summary><p>${esc(c.source_path)} · SHA-256 ${esc(c.source_sha256)}</p></details>`;}
 function renderM11jResults(){const host=$("m11j-current-run-values"),trace=app.trace,a=arm();if(!host)return;if(!trace||!a){host.innerHTML='<p class="ux-placeholder">Поточний run ще не створено. Перейдіть до Моделювання й виконайте явний запуск.</p>';return}const errors=a.symbols.flatMap((r,f)=>r.reference_comparison.bit_error_flags.map((v,k)=>v?f*2+k:null).filter(v=>v!==null)),bits=a.viterbi.decoded_bits.join(""),ref=trace.input.information_bits.join(""),width=720,marks=errors.map(k=>`<circle cx="${20+k*680/Math.max(bits.length-1,1)}" cy="45" r="8"><title>Помилка біта k=${k}</title></circle>`).join("");host.innerHTML=`<p>Run ${esc(m11jState.activeRunId||"unknown")} · ${m11jState.stale?'<b class="m11j-stale-text">STALE</b>':'ACTUAL RUN'}</p><div class="m11j-result-values"><article><small>Передані біти</small><code>${ref}</code></article><article><small>Декодовані біти</small><code>${bits}</code></article><article><small>Bit errors</small><b>${formatCount(a.reference_comparison.bit_errors)}</b></article><article><small>Symbol errors</small><b>${formatCount(a.reference_comparison.symbol_errors)}</b></article><article><small>BER</small><b>${formatRate(a.reference_comparison.ber)}</b></article><article><small>SER</small><b>${formatRate(a.reference_comparison.ser)}</b></article></div><h3>Позиції помилок у бітах</h3><svg class="m11j-error-chart" role="img" aria-label="Позиції помилок у бітах" viewBox="0 0 ${width} 90"><line x1="20" y1="45" x2="700" y2="45" class="ux-axis"/>${Array.from({length:bits.length},(_,k)=>`<line x1="${20+k*680/Math.max(bits.length-1,1)}" y1="38" x2="${20+k*680/Math.max(bits.length-1,1)}" y2="52" class="ux-axis"/>`).join("")}${marks}</svg><p>Один кадр є демонстрацією обчисленого trace, не статистичним доказом переваги policy.</p>`;}
 function m11jInstallSimulationSuccess(){const demo=$("view-demo");if($("m11j-run-confirmation"))return;demo.insertAdjacentHTML("afterbegin",`<div id="m11j-run-confirmation" class="card m11j-run-confirmation" hidden><b>Симуляцію завершено.</b><span> Активний результат: <b id="m11j-run-id-summary"></b></span><button id="m11j-view-signal" type="button" class="primary">Переглянути сигнал</button></div>`);$("m11j-view-signal").onclick=()=>viewUX("samples");}
 function m11jRefresh(){renderDemo();renderPipelineUX();renderSymbolUX();renderTrellisUX();renderEstimatorUX();renderDecodeUX();renderCompareUX();renderTablesUX();renderDefenseUX();paramsUX();renderSignalExplorer();renderBPreviewGraph();renderM11jStage();renderM11jDecoding();renderM11jResults();renderM11jSampleTable();renderM11jHidden();m11jUpdateStale();}
 function m11jInstallArchitecture(){if($("m11j-control-groups"))return;$("main").insertAdjacentHTML("afterbegin",`<div id="m11j-stale-banner" class="m11j-stale-banner" role="status" aria-live="polite" hidden></div>`);m11jOrganizeControls();m11jInstallStages();m11jInstallSamples();m11jInstallHidden();m11jInstallDecoding();m11jInstallResults();m11jInstallSimulationSuccess();document.querySelectorAll(".nav-item").forEach(b=>b.onclick=()=>viewUX(b.dataset.view));document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>viewUX(b.dataset.go));const observer=new MutationObserver(()=>{if($("m11hBPreview"))renderM11jHidden();const sec=document.querySelector("#encoder-b-result .b-trellis-projector");if(sec&&$("m11j-b-trellis-slot")&&!$("m11j-b-trellis-slot").contains(sec))$("m11j-b-trellis-slot").append(sec);const table=$("encoder-b-transition-table");if(table&&$("m11j-b-trellis-slot")&&!$("m11j-b-trellis-slot").contains(table))$("m11j-b-trellis-slot").append(table)});observer.observe($("encoder-b-result"),{childList:true,subtree:true});$("interactive-bits")?.addEventListener("input",()=>{const n=($("interactive-bits").value.match(/[01]/g)||[]).length;const display=$("m11j-frame-size");if(display)display.textContent=`Довжина кадру: ${n} інформаційних бітів · ${Math.floor(n/2)} TCM-символів`});}
 function m11jHandleStale(){if(!app.trace)return;const state=window.HFTCMMinimalistUIState||m11jState;state.stale=true;const banner=$("m11j-stale-banner");if(banner){banner.textContent=`STALE · configuration changed after run ${state.activeRunId}; displayed trace belongs to the previous configuration.`;banner.hidden=false;}document.body.dataset.traceStale="true";}
 function m11jBindStaleListeners(){for(const id of ["interactive-bits","interactive-template","interactive-encoder","interactive-state","receiver-mode","alpha","k-i","k-q","beta","noise-fixture"]){const el=$(id);if(el&&!el.dataset.m11jStaleBound){el.dataset.m11jStaleBound="1";el.addEventListener(id==="interactive-bits"?"input":"change",m11jHandleStale);}}}
